mapper.select:
SELECT

FROM TB_QUOTE Q
LEFT OUTER JOIN TB_CUSTOMER C ON C.CUST_ID = Q.CUST_ID


        Q.CUST_ID = #{custId}


        AND Q.STATUS_CD = #{statusCd}


        AND Q.QUOTE_DT >= #{fromDt}


        AND Q.QUOTE_DT <= #{toDt}


ORDER BY Q.QUOTE_DT DESC, Q.QUOTE_ID DESC
LIMIT #{startRow}, #{pageSize}
